// Nexora-India production storefront: one canonical customer application.
(()=>{
'use strict';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'₹'+Number(n||0).toLocaleString('en-IN',{maximumFractionDigits:2});
const $=s=>document.querySelector(s);
const state={sb:null,session:null,products:[],categories:[],settings:{},cart:[],routeToken:0};
const CART_KEY='nexora_cart';
function loadCart(){try{const x=JSON.parse(localStorage.getItem(CART_KEY)||'[]');state.cart=Array.isArray(x)?x.map(i=>({id:i.id,variant_id:i.variant_id||null,qty:Math.max(1,Number(i.qty)||1)})):[]}catch{state.cart=[]}}
function saveCart(){localStorage.setItem(CART_KEY,JSON.stringify(state.cart));updateNav()}
function cartKey(i){return `${i.id}:${i.variant_id||'base'}`}
function product(id){return state.products.find(p=>p.id===id)}
function category(id){return state.categories.find(c=>c.id===id)}
function variants(p){return Array.isArray(p?.product_variants)?p.product_variants.filter(v=>v.active!==false):[]}
function variantFor(p,id){return variants(p).find(v=>v.id===id)||null}
function priceFor(p,v){return Number(v?.selling_price??p?.selling_price??0)}
function stockFor(p,v){return Number(v?.stock??p?.stock??0)}
function minQty(p){return Math.max(1,Number(p?.min_order_qty||1))}
function discount(p,v){const mrp=Number(p?.mrp||0),price=priceFor(p,v);return mrp>price?Math.round((mrp-price)/mrp*100):0}
function cartCount(){return state.cart.reduce((s,i)=>s+i.qty,0)}
function cartRows(){return state.cart.map(i=>{const p=product(i.id);const v=p?variantFor(p,i.variant_id):null;return p?{...i,p,v,price:priceFor(p,v),stock:stockFor(p,v)}:null}).filter(Boolean)}
function cartTotals(){const rows=cartRows();let subtotal=0,shipping=0;for(const x of rows){subtotal+=x.price*x.qty;const electrical=x.p.electrical_mrp!=null;const charge=electrical?Number(x.p.electrical_delivery_charge||0):Number(x.p.delivery_charge||0);const fallback=electrical?Number(state.settings.electrical_delivery_charge||0):Number(state.settings.default_delivery_charge||0);if(state.settings.delivery_enabled!==false&&subtotal<Number(state.settings.free_delivery_min_amount||0))shipping+=(charge||fallback)*x.qty}return {rows,subtotal,shipping,total:Math.max(0,subtotal+shipping)}}
function setTitle(title,description){document.title=title?`${title} · Nexora-India`:'Nexora-India';let m=document.querySelector('meta[name=description]');if(!m){m=document.createElement('meta');m.name='description';document.head.appendChild(m)}m.content=description||'Nexora-India — smart shopping across footwear, daily-use essentials, kitchen appliances and artificial jewellery.'}
function setCanonical(){let link=document.querySelector('link[rel=canonical]');if(!link){link=document.createElement('link');link.rel='canonical';document.head.appendChild(link)}link.href=location.origin+location.pathname+location.hash}
function toast(text,type='success'){let e=$('#toast');if(!e){e=document.createElement('div');e.id='toast';document.body.appendChild(e)}e.className=`toast ${type}`;e.textContent=text;e.hidden=false;clearTimeout(e._t);e._t=setTimeout(()=>e.hidden=true,3200)}
function updateNav(){const logged=!!state.session;const c=$('#cartNav');if(c)c.innerHTML=`Cart <span class="nav-count">${cartCount()}</span>`;const a=$('#accountLink'),l=$('#loginLink'),o=$('#logoutBtn');if(a){a.hidden=!logged;a.textContent=state.session?.user?.user_metadata?.full_name||'Account'}if(l)l.hidden=logged;if(o)o.hidden=!logged}
async function api(path,options={}){const headers={'content-type':'application/json',...(options.headers||{})};if(state.session?.access_token)headers.Authorization=`Bearer ${state.session.access_token}`;const r=await fetch(`/api/${path}`,{...options,headers});const d=await r.json().catch(()=>({error:'Invalid server response'}));if(!r.ok)throw new Error(d.error||'Request failed');return d}
async function load(){const cfg=await fetch('/api/config',{cache:'no-store'}).then(async r=>{const d=await r.json();if(!r.ok||!d.url||!d.key)throw Error('Store authentication is not configured.');return d});state.sb=supabase.createClient(cfg.url,cfg.key,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});state.session=(await state.sb.auth.getSession()).data.session||null;state.sb.auth.onAuthStateChange((_e,s)=>{state.session=s||null;updateNav()});await Promise.all([loadCatalog(),loadSettings()]);loadCart();updateNav();route()}
async function loadCatalog(){const [c,p]=await Promise.all([state.sb.from('categories').select('id,name,slug,description,image_url,icon_url,banner_url,seo_title,seo_description,category_type,sort_order').eq('active',true).order('sort_order'),state.sb.from('products').select('id,name,slug,description,image_url,gallery,mrp,selling_price,stock,category_id,active,approved_by_admin,created_at,min_order_qty,delivery_charge,electrical_mrp,electrical_delivery_charge,product_variants(id,variant_name,attributes,sku,selling_price,stock,active)').eq('active',true).eq('approved_by_admin',true).order('created_at',{ascending:false})]);if(c.error)throw c.error;if(p.error)throw p.error;state.categories=c.data||[];state.products=p.data||[]}
async function loadSettings(){const r=await state.sb.from('admin_settings').select('store_name,store_email,upi_id,currency,guest_checkout_enabled,store_enabled,delivery_enabled,default_delivery_charge,electrical_delivery_charge,free_delivery_min_amount').limit(1).maybeSingle();if(!r.error&&r.data)state.settings=r.data}
function nav(){return `<header class="topbar"><a class="brand" href="#/"><span class="brand-mark">N</span><span>Nexora-India</span></a><nav><a href="#/products">Shop</a><a href="#/cart" id="cartNav">Cart</a><a href="#/login" id="loginLink">Login</a><a href="#/account/profile" id="accountLink" hidden>Account</a><button id="logoutBtn" class="nav-btn" hidden>Logout</button></nav></header>`}
function footer(){return `<footer><div class="footer-grid"><div><b>Nexora-India</b><p>Smart shopping with transparent pricing, secure accounts and order visibility.</p></div><div><b>Shop</b><a href="#/products">All products</a><a href="#/products?sort=newest">New arrivals</a><a href="#/cart">Cart</a></div><div><b>Customer care</b><a href="#/account/orders">My Orders</a><a href="#/account/support">Help & Support</a><a href="#/legal/contact">Contact</a></div><div><b>Policies</b><a href="#/legal/shipping">Shipping</a><a href="#/legal/returns">Returns & Refunds</a><a href="#/legal/privacy">Privacy</a><a href="#/legal/terms">Terms</a></div></div><div class="footer-bottom">© ${new Date().getFullYear()} Nexora-India · UPI payments · Secure checkout</div></footer>`}
function mount(html){document.body.innerHTML=`${nav()}<main id="app">${html}</main>${footer()}<div id="toast" class="toast" hidden></div>`;$('#logoutBtn')?.addEventListener('click',logout);updateNav()}
function home(){setTitle('Smart shopping');const cats=state.categories.map(c=>`<a class="cat-card" href="#/category/${encodeURIComponent(c.slug||c.id)}"><div class="cat-img"><img src="${esc(c.image_url||'https://placehold.co/700x460?text='+encodeURIComponent(c.name))}" alt="${esc(c.name)}" loading="lazy"></div><b>${esc(c.name)}</b><span>Explore products →</span></a>`).join('');const products=state.products.slice(0,8).map(card).join('');mount(`<div class="home"><section class="hero"><div><span class="eyebrow">NEXORA-INDIA · SMART SHOPPING</span><h1>Find something<br><em>you’ll love today.</em></h1><p>Discover useful products across footwear, daily-use essentials, kitchen appliances and artificial jewellery — in one clean store.</p><form class="hero-search" id="homeSearch"><input name="q" placeholder="Search products, categories or essentials…"><button>Search</button></form><div class="hero-actions"><a class="btn" href="#/products">Explore store</a><a class="btn secondary" href="#/products">Browse all products</a></div></div><div class="hero-art"><div class="hero-orbit">N</div><div class="hero-stat"><span>Live catalogue</span><b>${state.products.length}</b><small>approved products</small></div></div></section><section class="section"><div class="section-head"><div><span>SHOP BY CATEGORY</span><h2>What are you looking for?</h2></div><a href="#/products">View all →</a></div><div class="cat-grid">${cats||'<div class="empty">Categories are being prepared.</div>'}</div></section><section class="promo"><div><span>NEXORA PICKS</span><h2>Everyday finds, clearly priced.</h2><p>See stock, pricing, delivery and variants before you buy.</p></div><a class="btn" href="#/products">Shop products</a></section><section class="section"><div class="section-head"><div><span>FEATURED</span><h2>Popular picks</h2></div></div><div class="product-grid">${products||'<div class="empty">No products are published yet.</div>'}</div></section><section class="trust"><div><b>✓ Transparent pricing</b><small>See selling price, stock and delivery before checkout.</small></div><div><b>✓ Secure checkout</b><small>Authentication and server-side order validation protect purchases.</small></div><div><b>✓ Order visibility</b><small>Payment, shipping and tracking stay visible in your account.</small></div></section></div>`);$('#homeSearch').onsubmit=e=>{e.preventDefault();const q=new FormData(e.target).get('q');location.hash=`#/products?q=${encodeURIComponent(q||'')}`}}
function card(p){const c=category(p.category_id),d=discount(p),v=variants(p)[0]||null;return `<article class="product-card"><a href="#/product/${encodeURIComponent(p.slug||p.id)}"><div class="product-img"><img src="${esc(p.image_url||'https://placehold.co/700x560?text=Nexora-India')}" alt="${esc(p.name)}" loading="lazy">${d?`<span class="discount">${d}% OFF</span>`:''}</div></a><div class="product-body"><small>${esc(c?.name||'Product')}</small><h3><a href="#/product/${encodeURIComponent(p.slug||p.id)}">${esc(p.name)}</a></h3><div class="price">${money(priceFor(p,v))}${p.mrp&&Number(p.mrp)>priceFor(p,v)?` <del>${money(p.mrp)}</del>`:''}</div><div class="stock">${stockFor(p,v)>0?`${stockFor(p,v)} available`:'Out of stock'}</div><button class="btn full" ${stockFor(p,v)<1?'disabled':''} data-add="${p.id}">Add to cart</button></div></article>`}
function productList(){const h=location.hash||'#/products',qs=h.includes('?')?new URLSearchParams(h.split('?')[1]):new URLSearchParams(),q=(qs.get('q')||'').trim().toLowerCase(),cat=qs.get('cat')||'',sort=qs.get('sort')||'newest',min=Number(qs.get('min')||0),max=Number(qs.get('max')||0),stock=qs.get('stock')==='1';let a=state.products.filter(p=>{const text=(p.name+' '+(p.description||'')).toLowerCase();return (!q||text.includes(q))&&(!cat||p.category_id===cat)&&(!min||priceFor(p)>=min)&&(!max||priceFor(p)<=max)&&(!stock||stockFor(p)>0)});if(sort==='price_asc')a.sort((x,y)=>priceFor(x)-priceFor(y));else if(sort==='price_desc')a.sort((x,y)=>priceFor(y)-priceFor(x));else if(sort==='name')a.sort((x,y)=>x.name.localeCompare(y.name));else if(sort==='stock')a.sort((x,y)=>stockFor(y)-stockFor(x));else a.sort((x,y)=>new Date(y.created_at)-new Date(x.created_at));setTitle(q?`Search: ${q}`:'All products');mount(`<div class="page"><div class="page-head"><div><span>SHOPPING</span><h1>All products</h1><p>${a.length} product${a.length===1?'':'s'} found</p></div></div><form class="filters" id="filters"><input name="q" value="${esc(q)}" placeholder="Search products…"><select name="cat"><option value="">All categories</option>${state.categories.map(c=>`<option value="${c.id}" ${cat===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select><input name="min" type="number" min="0" value="${min||''}" placeholder="Min ₹"><input name="max" type="number" min="0" value="${max||''}" placeholder="Max ₹"><label><input type="checkbox" name="stock" ${stock?'checked':''}> In stock</label><select name="sort"><option value="newest" ${sort==='newest'?'selected':''}>Newest</option><option value="price_asc" ${sort==='price_asc'?'selected':''}>Price: low to high</option><option value="price_desc" ${sort==='price_desc'?'selected':''}>Price: high to low</option><option value="name" ${sort==='name'?'selected':''}>Name</option><option value="stock" ${sort==='stock'?'selected':''}>Availability</option></select><button class="btn">Apply</button></form><div class="product-grid">${a.map(card).join('')||'<div class="empty">No products match these filters.</div>'}</div></div>`);$('#filters').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),p=new URLSearchParams();for(const k of ['q','cat','min','max','sort'])if(f.get(k))p.set(k,f.get(k));if(f.get('stock'))p.set('stock','1');location.hash='#/products?'+p.toString()};bindAddButtons()}
function bindAddButtons(){document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>addToCart(b.dataset.add,null,1))}
function categoryPage(slug){const c=state.categories.find(x=>x.slug===slug||x.id===slug);if(!c)return notFound();setTitle(c.seo_title||c.name,c.seo_description||c.description);const ps=state.products.filter(p=>p.category_id===c.id);mount(`<div class="page"><div class="category-banner" style="background-image:linear-gradient(90deg,rgba(10,15,35,.9),rgba(10,15,35,.2)),url('${esc(c.banner_url||c.image_url||'https://placehold.co/1400x420?text='+encodeURIComponent(c.name))}')"><div><span>CATEGORY</span><h1>${esc(c.name)}</h1><p>${esc(c.description||'Explore approved products in this category.')}</p></div></div><div class="product-grid">${ps.map(card).join('')||'<div class="empty">No products are currently available in this category.</div>'}</div></div>`);bindAddButtons()}
async function productPage(key){const p=state.products.find(x=>x.id===key||x.slug===key);if(!p)return notFound();setTitle(p.name,p.description);let selected=variants(p)[0]?.id||null;const images=[p.image_url,...(Array.isArray(p.gallery)?p.gallery:[])].filter(Boolean);let reviews=[];try{const r=await state.sb.from('product_reviews').select('id,rating,title,body,verified_purchase,created_at').eq('product_id',p.id).eq('approved',true).order('created_at',{ascending:false});if(!r.error)reviews=r.data||[]}catch{}const render=()=>{const v=variantFor(p,selected),price=priceFor(p,v),stock=stockFor(p,v),d=discount(p,v);mount(`<div class="page detail"><div class="breadcrumbs"><a href="#/">Store</a> / <a href="#/category/${encodeURIComponent(category(p.category_id)?.slug||p.category_id)}">${esc(category(p.category_id)?.name||'Products')}</a> / ${esc(p.name)}</div><div class="detail-grid"><div><div class="detail-main"><img id="mainProductImage" src="${esc(images[0]||'https://placehold.co/900x760?text=Nexora-India')}" alt="${esc(p.name)}"></div><div class="thumbs">${images.map((im,i)=>`<button data-img="${esc(im)}" class="${i===0?'active':''}"><img src="${esc(im)}" alt=""></button>`).join('')}</div></div><div class="detail-info"><small>${esc(category(p.category_id)?.name||'Product')}</small><h1>${esc(p.name)}</h1><div class="detail-price">${money(price)} ${p.mrp&&Number(p.mrp)>price?`<del>${money(p.mrp)}</del><span class="discount">${d}% OFF</span>`:''}</div><div class="detail-stock ${stock>0?'in':'out'}">${stock>0?`✓ ${stock} available`:'Currently unavailable'}</div>${p.description?`<div class="description">${esc(p.description).replace(/\n/g,'<br>')}</div>`:''}${variants(p).length?`<div class="variant-box"><b>Choose option</b><div class="variant-list">${variants(p).map(x=>`<button data-variant="${x.id}" class="variant ${x.id===selected?'selected':''}">${esc(x.variant_name)}<small>${money(priceFor(p,x))} · ${stockFor(p,x)>0?'In stock':'Out'}</small></button>`).join('')}</div></div>`:''}<div class="detail-facts"><div><span>Delivery</span><b>${Number(p.delivery_charge||0)>0?money(p.delivery_charge):'Free'}</b></div><div><span>Minimum quantity</span><b>${minQty(p)}</b></div>${p.sku?`<div><span>SKU</span><b>${esc(p.sku)}</b></div>`:''}</div><div class="buy-row"><div class="qty"><button id="minus">−</button><span id="qty">${minQty(p)}</span><button id="plus">+</button></div><button class="btn" id="addDetail" ${stock<1?'disabled':''}>Add to cart</button><button class="btn secondary" id="buyDetail" ${stock<1?'disabled':''}>Buy now</button></div><div id="detailMsg"></div></div></div><section class="review-section"><div class="section-head"><div><span>REVIEWS</span><h2>Customer reviews</h2></div><button class="btn secondary" id="reviewBtn">Write a review</button></div>${reviews.length?reviews.map(r=>`<article class="review"><div class="rating">${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)}</div><b>${esc(r.title||'Customer review')}</b><p>${esc(r.body||'')}</p><small>${r.verified_purchase?'✓ Verified purchase · ':''}${new Date(r.created_at).toLocaleDateString('en-IN')}</small></article>`).join(''):'<div class="empty">No approved reviews yet.</div>'}</section></div>`);document.querySelectorAll('[data-variant]').forEach(b=>b.onclick=()=>{selected=b.dataset.variant;render()});document.querySelectorAll('[data-img]').forEach(b=>b.onclick=()=>{$('#mainProductImage').src=b.dataset.img;document.querySelectorAll('[data-img]').forEach(x=>x.classList.remove('active'));b.classList.add('active')});let qty=minQty(p);$('#minus').onclick=()=>{qty=Math.max(minQty(p),qty-1);$('#qty').textContent=qty};$('#plus').onclick=()=>{qty=Math.min(stockFor(p,variantFor(p,selected))||999,qty+1);$('#qty').textContent=qty};$('#addDetail').onclick=()=>addToCart(p.id,selected,qty);$('#buyDetail').onclick=()=>addToCart(p.id,selected,qty,true);$('#reviewBtn').onclick=()=>openReview(p.id)};render()}
async function openReview(productId){if(!state.session){location.hash='#/login?next='+encodeURIComponent(location.hash);return}const r=await state.sb.from('orders').select('id,order_number,order_items(product_id)').eq('user_id',state.session.user.id).order('created_at',{ascending:false});const eligible=(r.data||[]).filter(o=>(o.order_items||[]).some(i=>i.product_id===productId));const existing=await state.sb.from('product_reviews').select('id').eq('product_id',productId).eq('user_id',state.session.user.id).maybeSingle();if(existing.data){toast('You have already reviewed this product.','error');return}const box=document.createElement('div');box.className='modal';box.innerHTML=`<div class="modal-card"><button class="modal-x">×</button><h2>Write a review</h2>${eligible.length?`<select id="reviewOrder" class="input"><option value="">Select your order (optional)</option>${eligible.map(o=>`<option value="${o.id}">${esc(o.order_number)}</option>`).join('')}</select>`:'<div class="notice">You can review after purchasing this product.</div>'}<div class="stars" id="stars">${[1,2,3,4,5].map(n=>`<button data-rating="${n}">★</button>`).join('')}</div><input id="reviewTitle" class="input" placeholder="Review title"><textarea id="reviewBody" class="input" rows="5" placeholder="Tell other shoppers about your experience"></textarea><button class="btn" id="submitReview">Submit review</button><div id="reviewMsg"></div></div>`;document.body.appendChild(box);let rating=5;box.querySelectorAll('[data-rating]').forEach(b=>b.onclick=()=>{rating=Number(b.dataset.rating);box.querySelectorAll('[data-rating]').forEach(x=>x.classList.toggle('on',Number(x.dataset.rating)<=rating))});box.querySelector('[data-rating="5"]').classList.add('on');box.querySelector('.modal-x').onclick=()=>box.remove();box.querySelector('#submitReview').onclick=async()=>{const m=box.querySelector('#reviewMsg');try{const ins=await state.sb.from('product_reviews').insert({product_id:productId,user_id:state.session.user.id,order_id:box.querySelector('#reviewOrder')?.value||null,rating,title:box.querySelector('#reviewTitle').value.trim()||null,body:box.querySelector('#reviewBody').value.trim()||null});if(ins.error)throw ins.error;m.innerHTML='<div class="notice success">Review submitted for moderation.</div>';setTimeout(()=>box.remove(),1000)}catch(e){m.innerHTML=`<div class="notice error">${esc(e.message)}</div>`}}}
function addToCart(id,variantId,qty=1,buy=false){const p=product(id),v=p&&variantFor(p,variantId);if(!p)return;if(stockFor(p,v)<qty){toast('Requested quantity is not available.','error');return}const min=minQty(p);if(qty<min){toast(`Minimum order quantity is ${min}.`,'error');return}const k=cartKey({id,variant_id:variantId});const row=state.cart.find(x=>cartKey(x)===k);if(row)row.qty=Math.min(stockFor(p,v),row.qty+qty);else state.cart.push({id,variant_id:variantId||null,qty});saveCart();toast(`${p.name}${v?` — ${v.variant_name}`:''} added to cart.`);if(buy)location.hash='#/cart'}
function cartPage(){setTitle('Cart');const t=cartTotals();mount(`<div class="page"><div class="page-head"><div><span>YOUR CART</span><h1>Shopping cart</h1><p>${cartCount()} item${cartCount()===1?'':'s'}</p></div><a class="btn secondary" href="#/products">Continue shopping</a></div>${t.rows.length?`<div class="cart-layout"><section>${t.rows.map((x,i)=>`<article class="cart-row"><a href="#/product/${encodeURIComponent(x.p.slug||x.p.id)}"><img src="${esc(x.p.image_url||'https://placehold.co/300x240?text=Nexora-India')}" alt=""></a><div class="cart-main"><small>${esc(category(x.p.category_id)?.name||'Product')}</small><h2>${esc(x.p.name)}</h2>${x.v?`<div class="muted">${esc(x.v.variant_name)}</div>`:''}<b>${money(x.price)}</b><div class="cart-meta">${x.stock>0?`${x.stock} available`:'Out of stock'} · Minimum ${minQty(x.p)}</div><div class="cart-actions"><div class="qty"><button data-q="-" data-i="${i}">−</button><span>${x.qty}</span><button data-q="+" data-i="${i}">+</button></div><button class="link danger" data-remove="${i}">Remove</button><strong>${money(x.price*x.qty)}</strong></div></div></article>`).join('')}<button class="btn secondary" id="clearCart">Clear cart</button></section><aside class="summary"><h2>Order summary</h2><div><span>Subtotal</span><b>${money(t.subtotal)}</b></div><div><span>Delivery</span><b>${t.shipping?money(t.shipping):'Free'}</b></div><hr><div class="total"><span>Total</span><strong>${money(t.total)}</strong></div><a class="btn full" href="#/checkout">Proceed to checkout</a><small>Final stock, price, offers and delivery are verified server-side before the order is created.</small></aside></div>`:'<div class="empty cart-empty"><div class="big-icon">🛒</div><h2>Your cart is empty</h2><p>Add products you like and they will appear here.</p><a class="btn" href="#/products">Browse products</a></div>'}</div>`);document.querySelectorAll('[data-q]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.i),x=t.rows[i],row=state.cart.find(r=>cartKey(r)===cartKey(x));if(!row)return;const next=row.qty+(b.dataset.q==='+'?1:-1);if(next<minQty(x.p))row.qty=minQty(x.p);else if(next>x.stock)toast('Stock limit reached.','error');else row.qty=next;saveCart();cartPage()});document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{state.cart.splice(Number(b.dataset.remove),1);saveCart();cartPage()});$('#clearCart')?.addEventListener('click',()=>{state.cart=[];saveCart();cartPage()})}
async function checkoutPage(){if(!state.session){location.hash='#/login?next=%23%2Fcheckout';return}const t=cartTotals();if(!t.rows.length){location.hash='#/cart';return}setTitle('Checkout');const p=await state.sb.from('profiles').select('full_name,phone,address_line1,city,state,pincode').eq('id',state.session.user.id).maybeSingle();const profile=p.data||{};const upi=state.settings.upi_id||'';const amount=t.total;const upiLink=upi?`upi://pay?pa=${encodeURIComponent(upi)}&pn=${encodeURIComponent(state.settings.store_name||'Nexora-India')}&am=${encodeURIComponent(amount.toFixed(2))}&cu=INR`:'';mount(`<div class="page"><div class="page-head"><div><span>SECURE CHECKOUT</span><h1>Complete your order</h1><p>Review delivery details, pay by UPI and submit the reference number.</p></div></div><div class="checkout-layout"><section><div class="checkout-card"><h2>Delivery details</h2><div class="form-grid"><label>Full name<input id="coName" class="input" value="${esc(profile.full_name||'')}"></label><label>Mobile<input id="coPhone" class="input" value="${esc(profile.phone||'')}"></label><label class="full">Address<textarea id="coAddress" class="input" rows="3">${esc(profile.address_line1||'')}</textarea></label><label>City<input id="coCity" class="input" value="${esc(profile.city||'')}"></label><label>State<input id="coState" class="input" value="${esc(profile.state||'')}"></label><label>Pincode<input id="coPin" class="input" inputmode="numeric" maxlength="6" value="${esc(profile.pincode||'')}"></label><label class="full">Landmark (optional)<input id="coLandmark" class="input"></label></div></div><div class="checkout-card"><h2>UPI payment</h2>${upi?`<div class="upi-box"><div><b>Pay ${money(amount)}</b><p>UPI ID: <strong>${esc(upi)}</strong></p><button class="btn secondary" id="copyUpi">Copy UPI ID</button><a class="btn" href="${esc(upiLink)}">Open UPI app</a></div><img alt="UPI QR" src="https://api.qrserver.com/v1/create-qr-code/?size=220x220&data=${encodeURIComponent(upiLink)}"></div>`:'<div class="notice">UPI ID is not configured yet. You can still create a pending order and submit the UTR later.</div>'}<label>UPI UTR / Reference (optional now)<input id="coUtr" class="input" maxlength="64" placeholder="Enter 6–64 letters or numbers"></label><small>Payment is manually verified by admin. Never share your UPI PIN or OTP.</small></div><button class="btn full" id="placeOrder">Place order</button><div id="checkoutMsg"></div></section><aside class="summary"><h2>Order summary</h2>${t.rows.map(x=>`<div class="summary-item"><span>${esc(x.p.name)}${x.v?` — ${esc(x.v.variant_name)}`:''} × ${x.qty}</span><b>${money(x.price*x.qty)}</b></div>`).join('')}<hr><div><span>Subtotal</span><b>${money(t.subtotal)}</b></div><div><span>Delivery</span><b>${t.shipping?money(t.shipping):'Free'}</b></div><div class="total"><span>Total</span><strong>${money(t.total)}</strong></div></aside></div></div>`);$('#copyUpi')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(upi);toast('UPI ID copied')}catch{toast(upi)}});$('#placeOrder').onclick=async()=>{const b=$('#placeOrder'),msg=$('#checkoutMsg');b.disabled=true;b.textContent='Creating secure order…';try{const d=await api('order',{method:'POST',body:JSON.stringify({items:t.rows.map(x=>({product_id:x.p.id,variant_id:x.v?.id||null,quantity:x.qty})),customer:{name:$('#coName').value.trim(),phone:$('#coPhone').value.trim(),address_line1:$('#coAddress').value.trim(),city:$('#coCity').value.trim(),state:$('#coState').value.trim(),pincode:$('#coPin').value.trim(),landmark:$('#coLandmark').value.trim()},utr:$('#coUtr').value.trim()||null})});state.cart=[];saveCart();msg.innerHTML=`<div class="notice success"><b>Order ${esc(d.order_number)} created.</b><br>Total ${money(d.total_amount)} · Payment ${esc(d.payment_status)}<br><a href="#/account/orders">View My Orders →</a></div>`;b.remove();setTimeout(()=>location.hash='#/account/orders',1200)}catch(e){msg.innerHTML=`<div class="notice error">${esc(e.message)}</div>`;b.disabled=false;b.textContent='Place order'}}}
function authPage(mode){const next=new URLSearchParams(location.hash.split('?')[1]||'').get('next')||'#/account/profile';if(state.session&&!['forgot','reset'].includes(mode)){location.hash=next;return}const title=mode==='register'?'Create your account':mode==='forgot'?'Reset your password':'Login to Nexora-India';const body=mode==='register'?`<label>Full name<input id="authName" class="input"></label><label>Mobile<input id="authPhone" class="input"></label><label>Email<input id="authEmail" class="input" type="email"></label><label>Password<input id="authPass" class="input" type="password" minlength="8"></label><button class="btn full" id="authSubmit">Create account</button><p>Already registered? <a href="#/login">Login</a></p>`:mode==='forgot'?`<label>Email<input id="authEmail" class="input" type="email"></label><button class="btn full" id="authSubmit">Send reset email</button><p><a href="#/login">Back to login</a></p>`:`<label>Email<input id="authEmail" class="input" type="email"></label><label>Password<input id="authPass" class="input" type="password"></label><label class="check"><input id="remember" type="checkbox" checked> Keep me signed in</label><button class="btn full" id="authSubmit">Login</button><div class="auth-links"><a href="#/forgot">Forgot password?</a><a href="#/register">Create account</a></div>`;setTitle(title);mount(`<div class="auth-page"><div class="auth-card"><span>WELCOME TO NEXORA-INDIA</span><h1>${title}</h1>${body}<div id="authMsg"></div></div></div>`);$('#authSubmit').onclick=async()=>{const b=$('#authSubmit');b.disabled=true;try{if(mode==='register'){const email=$('#authEmail').value.trim(),pass=$('#authPass').value;if(pass.length<8)throw Error('Password must be at least 8 characters.');const r=await state.sb.auth.signUp({email,password:pass,options:{data:{full_name:$('#authName').value.trim(),phone:$('#authPhone').value.trim()}}});if(r.error)throw r.error;$('#authMsg').innerHTML=`<div class="notice success">Account created. ${r.data.session?'You are now signed in.':'Check your email to confirm your account.'}</div>`;if(r.data.session){state.session=r.data.session;location.hash=next}}else if(mode==='forgot'){const email=$('#authEmail').value.trim();if(!email)throw Error('Enter your email.');const r=await state.sb.auth.resetPasswordForEmail(email,{redirectTo:location.origin+location.pathname+'#/reset'});if(r.error)throw r.error;$('#authMsg').innerHTML='<div class="notice success">If the account exists, a password reset email has been sent.</div>'}else{const r=await state.sb.auth.signInWithPassword({email:$('#authEmail').value.trim(),password:$('#authPass').value});if(r.error)throw r.error;state.session=r.data.session;const aal=await state.sb.auth.mfa.getAuthenticatorAssuranceLevel();if(aal.data?.nextLevel==='aal2'&&aal.data?.currentLevel!=='aal2'){mfaLogin(next);return}location.hash=next}}catch(e){$('#authMsg').innerHTML=`<div class="notice error">${esc(e.message)}</div>`}finally{b.disabled=false}}}
function mfaLogin(next){mount(`<div class="auth-page"><div class="auth-card"><span>SECURITY CHECK</span><h1>Enter authenticator code</h1><p>Your account has MFA enabled.</p><input id="mfaCode" class="input" inputmode="numeric" maxlength="6" placeholder="6-digit code"><button class="btn full" id="mfaSubmit">Verify</button><div id="authMsg"></div></div></div>`);$('#mfaSubmit').onclick=async()=>{try{const f=await state.sb.auth.mfa.listFactors(),factor=f.data?.totp?.find(x=>x.status==='verified');if(!factor)throw Error('No verified authenticator factor found.');const r=await state.sb.auth.mfa.challengeAndVerify({factorId:factor.id,code:$('#mfaCode').value.trim()});if(r.error)throw r.error;state.session=(await state.sb.auth.getSession()).data.session;location.hash=next}catch(e){$('#authMsg').innerHTML=`<div class="notice error">${esc(e.message)}</div>`}}}
async function accountPage(tab){if(!state.session){location.hash='#/login?next='+encodeURIComponent(location.hash);return}const tabs=[['profile','Profile'],['orders','My Orders'],['addresses','Addresses'],['wishlist','Wishlist'],['notifications','Notifications'],['payments','Payments'],['security','Security'],['preferences','Preferences'],['support','Help & Support'],['privacy','Privacy']];mount(`<div class="page"><div class="page-head"><div><span>MY NEXORA</span><h1>My Account</h1><p>Manage your account, orders and security.</p></div></div><div class="account-layout"><aside class="account-nav">${tabs.map(x=>`<a class="${tab===x[0]?'active':''}" href="#/account/${x[0]}">${x[1]}</a>`).join('')}</aside><section id="accountPanel"><div class="account-card"><div class="muted">Loading…</div></div></section></div></div>`);await renderAccountTab(tab||'profile')}
async function renderAccountTab(tab){const p=$('#accountPanel');try{if(tab==='profile')return profileTab(p);if(tab==='orders')return ordersTab(p);if(tab==='addresses')return addressesTab(p);if(tab==='wishlist')return wishlistTab(p);if(tab==='notifications')return notificationsTab(p);if(tab==='payments')return paymentsTab(p);if(tab==='security')return securityTab(p);if(tab==='preferences')return preferencesTab(p);if(tab==='support')return supportTab(p);if(tab==='privacy')return privacyTab(p);return profileTab(p)}catch(e){p.innerHTML=`<div class="account-card"><div class="notice error">${esc(e.message)}</div></div>`}}
async function profileTab(p){const r=await state.sb.from('profiles').select('full_name,phone,address_line1,address_line2,city,state,pincode,date_of_birth,gender').eq('id',state.session.user.id).maybeSingle();if(r.error)throw r.error;const x=r.data||{};p.innerHTML=`<div class="account-card"><h2>Profile</h2><div class="form-grid"><label>Email<input class="input" disabled value="${esc(state.session.user.email)}"></label><label>Full name<input id="pfName" class="input" value="${esc(x.full_name||state.session.user.user_metadata?.full_name||'')}"></label><label>Mobile<input id="pfPhone" class="input" value="${esc(x.phone||'')}"></label><label>Date of birth<input id="pfDob" class="input" type="date" value="${esc(x.date_of_birth||'')}"></label><label>Gender<select id="pfGender" class="input"><option value="">Prefer not to say</option><option ${x.gender==='Male'?'selected':''}>Male</option><option ${x.gender==='Female'?'selected':''}>Female</option><option ${x.gender==='Other'?'selected':''}>Other</option></select></label><label class="full">Address line 1<input id="pfA1" class="input" value="${esc(x.address_line1||'')}"></label><label class="full">Address line 2<input id="pfA2" class="input" value="${esc(x.address_line2||'')}"></label><label>City<input id="pfCity" class="input" value="${esc(x.city||'')}"></label><label>State<input id="pfState" class="input" value="${esc(x.state||'')}"></label><label>Pincode<input id="pfPin" class="input" value="${esc(x.pincode||'')}"></label></div><button class="btn" id="saveProfile">Save changes</button><div id="profileMsg"></div></div>`;$('#saveProfile').onclick=async()=>{const u=await state.sb.from('profiles').update({full_name:$('#pfName').value.trim(),phone:$('#pfPhone').value.trim(),address_line1:$('#pfA1').value.trim(),address_line2:$('#pfA2').value.trim()||null,city:$('#pfCity').value.trim(),state:$('#pfState').value.trim(),pincode:$('#pfPin').value.trim(),date_of_birth:$('#pfDob').value||null,gender:$('#pfGender').value||null}).eq('id',state.session.user.id);$('#profileMsg').innerHTML=u.error?`<div class="notice error">${esc(u.error.message)}</div>`:'<div class="notice success">Profile updated.</div>'}}
async function ordersTab(p){const r=await state.sb.from('orders').select('id,order_number,created_at,total_amount,order_status,payment_status,shipping_status,tracking_number,tracking_url,carrier,order_items(product_name,quantity,unit_selling_price,variant_id)').eq('user_id',state.session.user.id).order('created_at',{ascending:false});if(r.error)throw r.error;p.innerHTML=`<div class="account-card"><h2>My Orders</h2>${(r.data||[]).map(o=>`<article class="order-card"><div class="between"><div><b>${esc(o.order_number)}</b><small>${new Date(o.created_at).toLocaleString('en-IN')}</small></div><span class="badge">${esc(o.order_status)}</span></div><div class="order-items">${(o.order_items||[]).map(i=>`${esc(i.product_name)} × ${i.quantity} — ${money(Number(i.unit_selling_price)*Number(i.quantity))}`).join('<br>')}</div><div class="order-foot"><b>${money(o.total_amount)}</b><span>Payment: ${esc(o.payment_status)}</span><span>Shipping: ${esc(o.shipping_status)}</span>${o.tracking_url?`<a class="btn secondary" target="_blank" rel="noopener" href="${esc(o.tracking_url)}">Track</a>`:''}${['PENDING_PAYMENT','PAYMENT_SUBMITTED'].includes(o.order_status)?`<button class="btn secondary" data-utr-order="${o.order_number}">Submit UTR</button>`:''}</div><div id="utr-${esc(o.order_number)}"></div></article>`).join('')||'<div class="empty">No orders yet.</div>'}</div>`;p.querySelectorAll('[data-utr-order]').forEach(b=>b.onclick=()=>utrForm(b.dataset.utrOrder))}
function utrForm(orderNumber){const box=document.getElementById('utr-'+CSS.escape(orderNumber));if(!box)return;box.innerHTML=`<div class="subcard"><label>UPI UTR / Reference<input id="utrInput" class="input" maxlength="64"></label><button class="btn" id="utrSend">Submit UTR</button><div id="utrMsg"></div></div>`;$('#utrSend').onclick=async()=>{try{await api('payment',{method:'POST',body:JSON.stringify({order_number:orderNumber,utr:$('#utrInput').value.trim()})});box.innerHTML='<div class="notice success">UTR submitted. Payment is awaiting admin verification.</div>';setTimeout(()=>accountPage('orders'),500)}catch(e){$('#utrMsg').innerHTML=`<div class="notice error">${esc(e.message)}</div>`}}}
async function addressesTab(p){const r=await state.sb.from('addresses').select('*').eq('user_id',state.session.user.id).order('is_default',{ascending:false}).order('created_at',{ascending:false});if(r.error)throw r.error;p.innerHTML=`<div class="account-card"><div class="between"><h2>Addresses</h2><button class="btn" id="addAddress">Add address</button></div><div id="addressList">${(r.data||[]).map(a=>`<article class="subcard"><div class="between"><b>${esc(a.name)} ${a.is_default?'<span class="badge">Default</span>':''}</b><span>${esc(a.phone)}</span></div><p>${esc(a.address_line1)}${a.address_line2?', '+esc(a.address_line2):''}, ${esc(a.city)}, ${esc(a.state)} - ${esc(a.pincode)}</p><div class="row"><button class="btn secondary" data-default="${a.id}">Set default</button><button class="link danger" data-delete="${a.id}">Delete</button></div></article>`).join('')||'<div class="empty">No saved addresses.</div>'}</div><div id="addressForm"></div></div>`;$('#addAddress').onclick=()=>showAddressForm(p);p.querySelectorAll('[data-default]').forEach(b=>b.onclick=async()=>{await state.sb.from('addresses').update({is_default:false}).eq('user_id',state.session.user.id);await state.sb.from('addresses').update({is_default:true}).eq('id',b.dataset.default).eq('user_id',state.session.user.id);addressesTab(p)});p.querySelectorAll('[data-delete]').forEach(b=>b.onclick=async()=>{if(confirm('Delete this address?')){await state.sb.from('addresses').delete().eq('id',b.dataset.delete).eq('user_id',state.session.user.id);addressesTab(p)}})}
function showAddressForm(p){$('#addressForm').innerHTML=`<div class="subcard"><h3>Add address</h3><div class="form-grid"><input id="adName" class="input" placeholder="Name"><input id="adPhone" class="input" placeholder="Mobile"><input id="ad1" class="input full" placeholder="Address line 1"><input id="ad2" class="input full" placeholder="Address line 2"><input id="adCity" class="input" placeholder="City"><input id="adState" class="input" placeholder="State"><input id="adPin" class="input" placeholder="Pincode"><input id="adLand" class="input" placeholder="Landmark"></div><label class="check"><input id="adDefault" type="checkbox"> Make default</label><button class="btn" id="adSave">Save address</button><div id="adMsg"></div></div>`;$('#adSave').onclick=async()=>{try{const x={user_id:state.session.user.id,name:$('#adName').value.trim(),phone:$('#adPhone').value.trim(),address_line1:$('#ad1').value.trim(),address_line2:$('#ad2').value.trim()||null,city:$('#adCity').value.trim(),state:$('#adState').value.trim(),pincode:$('#adPin').value.trim(),landmark:$('#adLand').value.trim()||null,is_default:$('#adDefault').checked};if(!x.name||!x.phone||!x.address_line1||!x.city||!x.state||!/^[0-9]{6}$/.test(x.pincode))throw Error('Complete address and valid 6-digit pincode are required.');if(x.is_default)await state.sb.from('addresses').update({is_default:false}).eq('user_id',state.session.user.id);const r=await state.sb.from('addresses').insert(x);if(r.error)throw r.error;addressesTab(p)}catch(e){$('#adMsg').innerHTML=`<div class="notice error">${esc(e.message)}</div>`}}}
async function wishlistTab(p){const r=await state.sb.from('wishlists').select('id,product_id,created_at,products(id,name,image_url,selling_price,stock,slug)').eq('user_id',state.session.user.id).order('created_at',{ascending:false});if(r.error)throw r.error;p.innerHTML=`<div class="account-card"><h2>Wishlist</h2>${(r.data||[]).map(w=>`<article class="subcard"><div class="between"><div><b>${esc(w.products?.name||'Product')}</b><div>${money(w.products?.selling_price)}</div></div><div class="row"><button class="btn" ${Number(w.products?.stock)>0?'':'disabled'} data-wish-add="${w.product_id}">Add to cart</button><button class="link danger" data-wish-remove="${w.id}">Remove</button></div></div></article>`).join('')||'<div class="empty">Wishlist is empty.</div>'}</div>`;p.querySelectorAll('[data-wish-add]').forEach(b=>b.onclick=()=>addToCart(b.dataset.wishAdd,null,1));p.querySelectorAll('[data-wish-remove]').forEach(b=>b.onclick=async()=>{await state.sb.from('wishlists').delete().eq('id',b.dataset.wishRemove).eq('user_id',state.session.user.id);wishlistTab(p)})}
async function notificationsTab(p){const r=await state.sb.from('notifications').select('*').eq('user_id',state.session.user.id).order('created_at',{ascending:false}).limit(50);if(r.error)throw r.error;p.innerHTML=`<div class="account-card"><div class="between"><h2>Notifications</h2><button class="btn secondary" id="markAll">Mark all read</button></div>${(r.data||[]).map(n=>`<article class="subcard ${n.is_read?'':'unread'}"><b>${esc(n.title)}</b><p>${esc(n.message)}</p><small>${new Date(n.created_at).toLocaleString('en-IN')}</small>${!n.is_read?`<button class="btn secondary" data-read="${n.id}">Mark read</button>`:''}</article>`).join('')||'<div class="empty">No notifications.</div>'}</div>`;$('#markAll').onclick=async()=>{await state.sb.from('notifications').update({is_read:true}).eq('user_id',state.session.user.id);notificationsTab(p)};p.querySelectorAll('[data-read]').forEach(b=>b.onclick=async()=>{await state.sb.from('notifications').update({is_read:true}).eq('id',b.dataset.read).eq('user_id',state.session.user.id);notificationsTab(p)})}
async function paymentsTab(p){const orders=await state.sb.from('orders').select('id,order_number,total_amount,payment_status,utr,created_at').eq('user_id',state.session.user.id).order('created_at',{ascending:false});if(orders.error)throw orders.error;p.innerHTML=`<div class="account-card"><h2>Payments</h2>${(orders.data||[]).map(o=>`<article class="subcard"><div class="between"><b>${esc(o.order_number)}</b><span class="badge">${esc(o.payment_status)}</span></div><p>Amount ${money(o.total_amount)} · UTR ${esc(o.utr||'Not submitted')}</p></article>`).join('')||'<div class="empty">No payment records.</div>'}</div>`}
async function securityTab(p){const factors=await state.sb.auth.mfa.listFactors();if(factors.error)throw factors.error;const verified=factors.data?.totp?.filter(x=>x.status==='verified')||[];p.innerHTML=`<div class="account-card"><h2>Security</h2><div class="subcard"><h3>Password</h3><p>Change your account password.</p><input id="newPass" class="input" type="password" minlength="8" placeholder="New password"><button class="btn" id="changePass">Update password</button><div id="passMsg"></div></div><div class="subcard"><h3>Authenticator app (TOTP)</h3><p>${verified.length?'MFA is enabled on this account.':'Add an authenticator app for stronger login protection.'}</p>${verified.map(f=>`<div class="between"><span>${esc(f.friendly_name||'Authenticator')}</span><button class="link danger" data-unenroll="${f.id}">Remove</button></div>`).join('')}${!verified.length?'<button class="btn" id="enrollMfa">Enable authenticator</button>':''}<div id="mfaBox"></div></div></div>`;$('#changePass').onclick=async()=>{try{const pass=$('#newPass').value;if(pass.length<8)throw Error('Password must be at least 8 characters.');const r=await state.sb.auth.updateUser({password:pass});if(r.error)throw r.error;$('#passMsg').innerHTML='<div class="notice success">Password updated.</div>'}catch(e){$('#passMsg').innerHTML=`<div class="notice error">${esc(e.message)}</div>`}};$('#enrollMfa')?.addEventListener('click',enrollMfa);p.querySelectorAll('[data-unenroll]').forEach(b=>b.onclick=async()=>{try{const r=await state.sb.auth.unenroll({factorId:b.dataset.unenroll});if(r.error)throw r.error;securityTab(p)}catch(e){toast(e.message,'error')}})}
async function enrollMfa(){const box=$('#mfaBox');try{const r=await state.sb.auth.mfa.enroll({factorType:'totp',friendlyName:'Nexora-India'});if(r.error)throw r.error;const f=r.data;box.innerHTML=`<div class="mfa-enroll"><img src="data:image/svg+xml;utf8,${encodeURIComponent(f.totp.qr_code)}" alt="Scan with authenticator"><p>Secret: <code>${esc(f.totp.secret)}</code></p><input id="mfaEnrollCode" class="input" inputmode="numeric" maxlength="6" placeholder="6-digit code"><button class="btn" id="verifyMfa">Enable</button><div id="mfaMsg"></div></div>`;$('#verifyMfa').onclick=async()=>{try{const ch=await state.sb.auth.mfa.challenge({factorId:f.id});if(ch.error)throw ch.error;const v=await state.sb.auth.mfa.verify({factorId:f.id,challengeId:ch.data.id,code:$('#mfaEnrollCode').value.trim()});if(v.error)throw v.error;toast('Authenticator enabled');securityTab($('#accountPanel'))}catch(e){$('#mfaMsg').innerHTML=`<div class="notice error">${esc(e.message)}</div>`}}}catch(e){box.innerHTML=`<div class="notice error">${esc(e.message)}</div>`}}
async function preferencesTab(p){const r=await state.sb.from('user_preferences').select('*').eq('user_id',state.session.user.id).maybeSingle();const x=r.data||{};p.innerHTML=`<div class="account-card"><h2>Preferences</h2><label>Language<select id="prefLang" class="input"><option ${x.language==='English'||!x.language?'selected':''}>English</option><option ${x.language==='Hindi'?'selected':''}>Hindi</option></select></label><label>Currency<input class="input" value="INR" disabled></label><label class="check"><input id="prefEmail" type="checkbox" ${x.email_notifications!==false?'checked':''}> Email notifications</label><label class="check"><input id="prefSms" type="checkbox" ${x.sms_notifications!==false?'checked':''}> SMS notifications</label><label class="check"><input id="prefMarketing" type="checkbox" ${x.marketing_notifications?'checked':''}> Marketing notifications</label><button class="btn" id="savePrefs">Save preferences</button><div id="prefMsg"></div></div>`;$('#savePrefs').onclick=async()=>{const u=await state.sb.from('user_preferences').upsert({user_id:state.session.user.id,language:$('#prefLang').value,currency:'INR',email_notifications:$('#prefEmail').checked,sms_notifications:$('#prefSms').checked,marketing_notifications:$('#prefMarketing').checked},{onConflict:'user_id'});$('#prefMsg').innerHTML=u.error?`<div class="notice error">${esc(u.error.message)}</div>`:'<div class="notice success">Preferences saved.</div>'}}
async function supportTab(p){const r=await state.sb.from('support_tickets').select('*').eq('user_id',state.session.user.id).order('created_at',{ascending:false});if(r.error)throw r.error;p.innerHTML=`<div class="account-card"><h2>Help & Support</h2><div class="subcard"><h3>Open a support ticket</h3><input id="ticketSubject" class="input" placeholder="Subject"><textarea id="ticketMessage" class="input" rows="4" placeholder="Describe your issue"></textarea><button class="btn" id="ticketSend">Create ticket</button><div id="ticketMsg"></div></div>${(r.data||[]).map(t=>`<article class="subcard"><div class="between"><b>${esc(t.subject)}</b><span class="badge">${esc(t.status)}</span></div><p>${esc(t.message)}</p><small>${new Date(t.created_at).toLocaleString('en-IN')}</small></article>`).join('')}</div>`;$('#ticketSend').onclick=async()=>{try{const x={user_id:state.session.user.id,subject:$('#ticketSubject').value.trim(),message:$('#ticketMessage').value.trim()};if(!x.subject||!x.message)throw Error('Subject and message are required.');const r=await state.sb.from('support_tickets').insert(x);if(r.error)throw r.error;supportTab(p)}catch(e){$('#ticketMsg').innerHTML=`<div class="notice error">${esc(e.message)}</div>`}}}
async function privacyTab(p){const r=await state.sb.from('account_deletion_requests').select('*').eq('user_id',state.session.user.id).maybeSingle();p.innerHTML=`<div class="account-card"><h2>Privacy & account</h2><p>Your personal data is protected by account-level access controls. You can request account deletion; order records may be retained where legally or operationally necessary.</p>${r.data?`<div class="notice">Deletion request status: <b>${esc(r.data.status)}</b></div>`:`<div class="subcard"><textarea id="delReason" class="input" rows="3" placeholder="Optional reason for deletion"></textarea><button class="btn danger" id="requestDelete">Request account deletion</button><div id="delMsg"></div></div>`}</div>`;$('#requestDelete')?.addEventListener('click',async()=>{try{const x={user_id:state.session.user.id,reason:$('#delReason').value.trim()||null};const q=await state.sb.from('account_deletion_requests').insert(x);if(q.error)throw q.error;privacyTab(p)}catch(e){$('#delMsg').innerHTML=`<div class="notice error">${esc(e.message)}</div>`}})}
function legalPage(type){const docs={shipping:['Shipping Policy','Orders are dispatched after payment verification. Delivery times depend on supplier and carrier performance. Tracking information is shown in My Orders when available.'],returns:['Returns & Refunds','Return eligibility depends on product condition and supplier policy. Contact support with your order number and issue promptly after delivery. Refunds, where approved, are processed after the return/verification process.'],privacy:['Privacy Policy','Nexora-India uses account, order and payment-reference information only to operate the store, provide support, prevent fraud and fulfil orders. Payment credentials such as UPI PINs are never requested or stored.'],terms:['Terms & Conditions','By using Nexora-India you agree to provide accurate delivery information, use the store lawfully and pay for orders you place. Product availability, pricing and delivery are subject to server-side validation and supplier availability.'],contact:['Contact Us','For order, payment, delivery or account help, open a support ticket from My Account. Include your order number and a concise description so the issue can be handled efficiently.'],cancellation:['Cancellation Policy','An order can be cancelled before fulfilment where operationally possible. Once supplier processing or shipment has begun, cancellation may require a return/refund process.']};const d=docs[type]||docs.terms;setTitle(d[0]);mount(`<div class="page legal"><div class="legal-card"><span>NEXORA-INDIA</span><h1>${d[0]}</h1><p>${d[1]}</p><h2>Need help?</h2><p><a href="#/account/support">Open Help & Support</a> or review <a href="#/legal/contact">Contact Us</a>.</p></div></div>`)}
function notFound(){setTitle('Page not found');mount('<div class="page"><div class="empty"><h1>Page not found</h1><a class="btn" href="#/">Back to store</a></div></div>')}
async function logout(){await state.sb?.auth.signOut();state.session=null;updateNav();location.hash='#/'}
async function route(){const h=location.hash||'#/';setCanonical();if(h==='#/'||h==='#')return home();if(h.startsWith('#/products'))return productList();if(h.startsWith('#/category/'))return categoryPage(decodeURIComponent(h.split('/')[2]||''));if(h.startsWith('#/product/'))return productPage(decodeURIComponent(h.split('/')[2]||''));if(h==='#/cart')return cartPage();if(h==='#/checkout')return checkoutPage();if(h==='#/login')return authPage('login');if(h==='#/register')return authPage('register');if(h==='#/forgot')return authPage('forgot');if(h==='#/reset'){if(!state.session)return authPage('login');setTitle('Set new password');mount(`<div class="auth-page"><div class="auth-card"><h1>Set a new password</h1><input id="resetPass" class="input" type="password" minlength="8" placeholder="New password"><button class="btn full" id="resetBtn">Update password</button><div id="resetMsg"></div></div></div>`);$('#resetBtn').onclick=async()=>{try{const pass=$('#resetPass').value;if(pass.length<8)throw Error('Password must be at least 8 characters.');const r=await state.sb.auth.updateUser({password:pass});if(r.error)throw r.error;$('#resetMsg').innerHTML='<div class="notice success">Password updated. You can continue shopping.</div>';setTimeout(()=>location.hash='#/account/security',700)}catch(e){$('#resetMsg').innerHTML=`<div class="notice error">${esc(e.message)}</div>`}};return}if(h.startsWith('#/account'))return accountPage((h.split('/')[2]||'profile').split('?')[0]);if(h.startsWith('#/legal/'))return legalPage(h.split('/')[2]);return notFound()}
window.addEventListener('hashchange',()=>route());
load().catch(e=>{console.error(e);document.body.innerHTML=`<main class="fatal"><h1>Nexora-India</h1><p>${esc(e.message||'Store failed to initialise.')}</p></main>`});
})();
